package com.crm.lead.controller;
import com.crm.lead.entity.Lead; import com.crm.lead.repository.LeadRepository; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/leads") public class LeadController { private final LeadRepository repo; public LeadController(LeadRepository repo){this.repo=repo;} @GetMapping public List<Lead> all(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Lead> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public ResponseEntity<Lead> create(@Valid @RequestBody Lead x){return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(x));} @PutMapping("/{id}") public ResponseEntity<Lead> update(@PathVariable Long id,@RequestBody Lead x){return repo.findById(id).map(e->{e.setName(x.getName());e.setEmail(x.getEmail());e.setPhone(x.getPhone());e.setStatus(x.getStatus());e.setCustomerId(x.getCustomerId());return ResponseEntity.ok(repo.save(e));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }